CREATE OR REPLACE FUNCTION public.fetch_thread_messages(p_client_id uuid, p_before timestamptz DEFAULT NULL, p_limit int DEFAULT 50) RETURNS SETOF public.coach_messages LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid uuid := auth.uid(); v_limit int := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100); BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF p_client_id IS NULL THEN RAISE EXCEPTION 'Client required'; END IF; IF p_client_id <> v_uid AND NOT public.is_coach_of(p_client_id) THEN IF NOT EXISTS (SELECT 1 FROM public.coach_messages m WHERE m.coach_id = v_uid AND m.client_id = p_client_id) THEN RAISE EXCEPTION 'Not authorized for this thread'; END IF; END IF; RETURN QUERY SELECT m.* FROM public.coach_messages m WHERE m.client_id = p_client_id AND (p_before IS NULL OR m.created_at < p_before) AND (m.client_id = v_uid OR m.coach_id = v_uid) ORDER BY m.created_at DESC LIMIT v_limit; END; $$; REVOKE ALL ON FUNCTION public.fetch_thread_messages(uuid, timestamptz, int) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.fetch_thread_messages(uuid, timestamptz, int) TO authenticated; CREATE OR REPLACE FUNCTION public.count_unread_messages() RETURNS TABLE (client_id uuid, unread_count bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid uuid := auth.uid(); BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; RETURN QUERY SELECT m.client_id, COUNT(*)::bigint FROM public.coach_messages m WHERE m.read_at IS NULL AND m.sender_id <> v_uid AND (m.coach_id = v_uid OR m.client_id = v_uid) GROUP BY m.client_id; END; $$; REVOKE ALL ON FUNCTION public.count_unread_messages() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.count_unread_messages() TO authenticated;
